// Mock fixtures for VITE_MOCK=1. The events are REAL recorder events generated by the Python
// simulator (trail.synthetic.Writer) via fixtures/make_fixtures.py, so replay, analysis and
// the designer's time-lapse behave exactly as they will with a live extension.
//
// Three essays use a fixture verbatim. Seven more are derived from the same fixtures so the Time page's
// "Your pace" section has a record to read: the fixture's events are split into several sessions on
// recent evenings (relative to today), their timing stretched so the pace is a student's rather than a
// simulator's, and the hash chain recomputed so each derived record is self-consistent.
import type { Checkpoint, Essay, Me, TrailEvent, WorklogRow } from './types';
import { analyse, tsMicros } from './analysis';
import { GENESIS_HASH, eventHash, hashValue } from './canonical';
import mixed from './fixtures/mock-mixed.json';
import heavy from './fixtures/mock-heavy_paster.json';
import honest from './fixtures/mock-honest.json';

