/** A stable uuid-shaped id from any seed, so the mock looks the same on every reload. */
function uuidFrom(seed: unknown): string {
  const h = hashValue(seed);
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-4${h.slice(13, 16)}-a${h.slice(17, 20)}-${h.slice(20, 32)}`;
}

/** Microseconds since the epoch to the recorder's "%Y-%m-%dT%H:%M:%S.%fZ". */
function fmtTs(us: number): string {
  const sec = Math.floor(us / 1_000_000);
  const frac = us - sec * 1_000_000;
  return `${new Date(sec * 1000).toISOString().slice(0, 19)}.${String(frac).padStart(6, '0')}Z`;
}

function localStart(now: number, ago: number, h: number, m: number): number {
  const d = new Date(now);
  d.setHours(0, 0, 0, 0);
  d.setDate(d.getDate() - ago);
  d.setHours(h, m, 0, 0);
  return d.getTime();
}

function deriveEvents(spec: DerivedSpec, now: number): TrailEvent[] {
  const src = spec.base.events;
  const doc = uuidFrom(['doc', spec.title]);
  const startEv = src.find((e) => e.kind === 'session.start');
  const endEv = src.find((e) => e.kind === 'session.end');
  const body = src.filter((e) => e.kind !== 'session.start' && e.kind !== 'session.end');
  const k = spec.sessions.length;
  const out: TrailEvent[] = [];
  for (let c = 0; c < k; c++) {
    const from = Math.floor((body.length * c) / k);
    const to = Math.floor((body.length * (c + 1)) / k);
    const chunk = body.slice(from, to);
    if (!chunk.length) continue;
    const [ago, h, m] = spec.sessions[c];
    const sessionStartUs = localStart(now, ago, h, m) * 1000;
    const session = uuidFrom(['session', doc, c]);
    const firstUs = tsMicros(chunk[0].ts);
    const shift = (ts: string) => sessionStartUs + 2_000_000 + Math.round((tsMicros(ts) - firstUs) * spec.stretch);
    let prev = GENESIS_HASH;
    let seq = 0;
    const push = (kind: string, ts: string, data: Record<string, any>) => {
      const ev: TrailEvent = { v: 1, id: uuidFrom(['event', session, seq]), seq, session, doc, ts, kind, data, prev, hash: '' };
      ev.hash = eventHash(ev);
      prev = ev.hash;
      seq += 1;
      out.push(ev);
    };
    push('session.start', fmtTs(sessionStartUs), { ...(startEv?.data ?? {}), editor: spec.editor, host: spec.host });
    for (const e of chunk) push(e.kind, fmtTs(shift(e.ts)), e.data);
    push('session.end', fmtTs(shift(chunk[chunk.length - 1].ts) + 1_000_000), endEv?.data ?? {});
  }
  return out;
}

const NOW = Date.now();
const SOURCES: { title: string; editor: string; events: TrailEvent[] }[] = [
  ...FIXTURES.map(({ title, editor, fixture }) => ({ title, editor, events: fixture.events })),
  ...DERIVED.map((spec) => ({ title: spec.title, editor: spec.editor, events: deriveEvents(spec, NOW) })),
];

export const mockEvents = new Map<string, TrailEvent[]>();
export const mockEssays: Essay[] = SOURCES.map(({ title, editor, events }) => {
  const id = events[0].doc;
  mockEvents.set(id, events);
  const a = analyse(events);
  return {
    id,
    title,
    editor,
    firstSeen: a.first_event || events[0].ts,
    lastSeen: a.last_event || events[events.length - 1].ts,
    typed: a.cadence.typed_chars,
    pasted: a.pastes.pasted_chars,
    deleted: a.cadence.deleted_chars,
    events: events.length,
    sessions: a.sessions.length,
    words: a.document.final_words,
  };
});

