export function mockCheckpoints(id: string): Checkpoint[] {
  const events = mockEvents.get(id);
  if (!events) return [];
  // A plausible, unsigned-looking checkpoint shape for layout work; signatures are not real.
  const heads: Record<string, { seq: number; hash: string; first_ts: string }> = {};
  for (const e of events) {
    const h = heads[e.session];
    if (!h) heads[e.session] = { seq: e.seq, hash: e.hash, first_ts: e.ts };
    else if (e.seq > h.seq) {
      h.seq = e.seq;
      h.hash = e.hash;
    }
  }
  const last = events[events.length - 1];
  return [
    {
      body: { v: 1, tenant: 'mock-user', agent: id, ts: last.ts, seq: 0, prev_checkpoint: '0'.repeat(64), heads, heads_root: 'a'.repeat(64), events: events.length },
      signature: 'bW9jay1zaWduYXR1cmU=',
      key_id: 'mock0000key00001',
      hash: 'b'.repeat(64),
    },
  ];
}

