let worklogCache: WorklogRow[] | null = null;
export function mockWorklog(now = NOW): WorklogRow[] {
  if (worklogCache) return worklogCache;
  const today = new Date(now);
  today.setHours(0, 0, 0, 0);
  const pad = (n: number) => String(n).padStart(2, '0');
  const dayOf = (d: Date) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  const rowOf = (id: string, it: MockItem, start: Date, end: Date, activeMs: number): WorklogRow => ({
    id,
    host: it.host,
    editor: it.editor,
    kind: it.kind,
    course_key: it.course_key,
    course_label: it.course_label,
    item_key: it.item_key,
    item_label: it.item_label,
    doc: it.doc ?? null,
    start: start.toISOString(),
    end: end.toISOString(),
    active_ms: activeMs,
    day: dayOf(start),
    heartbeats: Math.round(activeMs / 15_000),
  });
  const rows = MOCK_STINTS.map(([ago, h, m, wall, active, idx], i) => {
    const start = new Date(today);
    start.setDate(start.getDate() - ago);
    start.setHours(h, m, 0, 0);
    return rowOf(`wl-${i + 1}`, MOCK_ITEMS[idx], start, new Date(start.getTime() + wall * 60_000), active * 60_000);
  });
  // The derived essays' own stints: the tab was in front from two minutes before each writing session
  // to three minutes after it, so the merge rule has a presence row and a session for the same sitting.
  DERIVED_ITEMS.forEach((it, i) => {
    const bySession = new Map<string, { start: number; end: number }>();
    for (const e of mockEvents.get(it.doc!) || []) {
      const t = Math.floor(tsMicros(e.ts) / 1000);
      const s = bySession.get(e.session);
      if (!s) bySession.set(e.session, { start: t, end: t });
      else s.end = Math.max(s.end, t);
    }
    [...bySession.values()].forEach((s, j) => {
      const start = new Date(s.start - 2 * 60_000);
      const end = new Date(s.end + 3 * 60_000);
      rows.push(rowOf(`wl-d${i + 1}-${j + 1}`, it, start, end, Math.round((end.getTime() - start.getTime()) * 0.85)));
    });
  });
  rows.sort((a, b) => (a.start < b.start ? -1 : a.start > b.start ? 1 : 0));
  worklogCache = rows;
  return worklogCache;
}
